INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "邛州粮尽，毛湘请任可知持首归王建", "start_year": 890, "end_year": 890, "time_original": "890年闰月壬戌", "dynasty": "唐", "description": "王建急攻邛州，毛湘粮尽而救兵不到，向任可知表示不忍负田令孜、吏民无罪，愿其持己首归王建，随后沐浴待死。", "phases": [], "location_name": "邛州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "58b06203-d8c1-588c-ad00-63263ac082c5"}, {"title": "任可知斩毛湘及二子降王建", "start_year": 890, "end_year": 890, "time_original": "890年闰月壬戌条", "dynasty": "唐", "description": "任可知斩毛湘及其二子后投降王建，《通鉴》记士民皆泣。", "phases": [], "location_name": "邛州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d8343307-07b4-528e-a6bf-c9ed8cf99b80"}, {"title": "王建持永平旌节入邛州，张琳知留后", "start_year": 890, "end_year": 890, "time_original": "890年闰月甲戌", "dynasty": "唐", "description": "王建持永平旌节进入邛州，以节度判官张琳知留后，修整城隍，抚安夷獠，经营蜀、雅。", "phases": [], "location_name": "邛州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "69644dfa-3204-567b-8f12-6ca218119d72"}, {"title": "王建回兵成都，李行周以蜀州降", "start_year": 890, "end_year": 890, "time_original": "890年十月癸未朔", "dynasty": "唐", "description": "王建率兵返回成都，蜀州将李行周驱逐徐公鉥，举城投降王建。", "phases": [], "location_name": "成都、蜀州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d9cfc0d4-1da5-563f-9984-049a08019f43"}, {"title": "朱全忠赴滑州，魏镇拒粮马借道", "start_year": 890, "end_year": 890, "time_original": "890年十月乙酉", "dynasty": "唐", "description": "朱全忠自河阳赴滑州视事，向魏请求粮马与借道讨河东，罗弘信不许；再向镇请求，镇人亦不许。", "phases": [], "location_name": "河阳、滑州、魏、镇", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "705cd9ed-6f75-57b5-ab58-02cf64733443"}, {"title": "朱全忠自黎阳渡河攻魏", "start_year": 890, "end_year": 890, "time_original": "890年十月乙酉条后", "dynasty": "唐", "description": "借道请求被拒后，朱全忠自黎阳渡河进攻魏。", "phases": [], "location_name": "黎阳、魏", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "37f52215-7f89-5fbf-ae0a-00f3e249dd7d"}, {"title": "王行瑜加侍中，张全义加同平章事", "start_year": 890, "end_year": 890, "time_original": "890年十月后条；具体日未载", "dynasty": "唐", "description": "朝廷加邠宁节度使王行瑜侍中，加佑国节度使张全义同平章事。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "bae1b888-1091-5ba4-a961-fa2c388557f9"}, {"title": "官军出阴地关，河东军驻洪洞赵城", "start_year": 890, "end_year": 890, "time_original": "890年十一月条前；具体日未载", "dynasty": "唐", "description": "官军出阴地关，游兵至汾州；李克用遣薛志勤、李承嗣驻洪洞，李存孝驻赵城。", "phases": [], "location_name": "阴地关、汾州、洪洞、赵城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "dafdab69-8928-5d34-a5d0-588f0231c405"}, {"title": "韩建夜袭李存孝营受伏，官军溃退", "start_year": 890, "end_year": 890, "time_original": "890年十一月条前；具体日未载", "dynasty": "唐", "description": "韩建率壮士夜袭李存孝营，李存孝预知设伏，韩建兵不利；静难、凤翔军不战而走，禁军溃散，河东军追抵晋州西门。", "phases": [], "location_name": "赵城、晋州西门", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "285a266b-d8ea-540e-a964-27c0fd510e03"}, {"title": "张浚出战再败，与韩建闭守晋州", "start_year": 890, "end_year": 890, "time_original": "890年十一月条前；具体日未载", "dynasty": "唐", "description": "张浚出战再败，官军死者书载近三千。诸镇军先渡河西归，张浚所余禁军、宣武军与韩建闭城防守，此后不敢再出。", "phases": [], "location_name": "晋州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f52da050-517c-560b-8dd0-45638ef873a5"}, {"title": "李存孝攻绛州，张行恭弃城", "start_year": 890, "end_year": 890, "time_original": "890年十一月", "dynasty": "唐", "description": "李存孝率军攻绛州，刺史张行恭弃城逃走。", "phases": [], "location_name": "绛州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "34fc8cda-ceff-5bc3-9818-8d1ab7473711"}, {"title": "李存孝退军，张浚韩建逃离晋州", "start_year": 890, "end_year": 890, "time_original": "890年十一月；攻晋州三日后", "dynasty": "唐", "description": "李存孝攻晋州三日后，与部众议称俘宰相无益、天子禁兵不宜加害，遂后退驻军；张浚、韩建自含口逃去。", "phases": [], "location_name": "晋州、含口", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "53495763-016e-5073-a38a-c62a6131ee5c"}, {"title": "李存孝取晋绛并掠慈隰", "start_year": 890, "end_year": 890, "time_original": "890年十一月；张浚韩建逃后", "dynasty": "唐", "description": "李存孝取得晋、绛二州，并大掠慈、隰境内。", "phases": [], "location_name": "晋州、绛州、慈州、隰州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c2ded1d4-16f1-5a93-9f89-be27d5a8ca02"}, {"title": "李克用遣韩归范归朝诉冤的前事", "start_year": null, "end_year": null, "time_original": "张浚战败以前；具体年日未载", "dynasty": "唐", "description": "李克用此前遣韩归范归朝附表申冤，列举三代四朝功劳，批评朝廷赏他镇而罚河东，并称已集兵五十万，欲与张浚决战或入朝自诉。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b1e5a73d-f301-588c-ba40-89c29a41d98d"}, {"title": "张浚韩建越王屋至河阳渡河", "start_year": 890, "end_year": 890, "time_original": "890年十一月条后；具体日未载", "dynasty": "唐", "description": "李克用奏表抵朝时张浚已败，朝廷震恐；张浚、韩建越王屋至河阳，拆民屋作筏渡河，书载师徒失亡殆尽。", "phases": [], "location_name": "王屋、河阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5b828129-9a4c-55aa-9b42-a2b9deced69f"}, {"title": "通鉴评河东之役协同失利", "start_year": null, "end_year": null, "time_original": "河东之役回顾；非独立确日事件", "dynasty": "唐", "description": "《通鉴》总述朝廷原倚朱全忠及河朔三镇，但朱全忠正战徐郓，虽遣将攻泽州而本人未至；镇魏不出兵粮，孙揆被擒、幽云败军及杨复恭居中阻挠，官军遂溃。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "22545e66-0b36-50da-b60f-68b6fb534a96"}, {"title": "孙儒取苏州杀李友", "start_year": 890, "end_year": 890, "time_original": "890年十二月己丑", "dynasty": "唐", "description": "孙儒攻取苏州，杀李友。", "phases": [], "location_name": "苏州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5f401fe1-4249-51e2-880f-2073105059db"}, {"title": "安仁义等焚润州庐舍夜撤", "start_year": 890, "end_year": 890, "time_original": "890年十二月己丑条；闻苏州失后", "dynasty": "唐", "description": "安仁义等闻苏州失陷，焚烧润州庐舍，夜间撤离。", "phases": [], "location_name": "润州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "26262436-2c3b-5194-a576-ed2162671ffe"}, {"title": "沈粲归传道受孙儒命分守苏润", "start_year": 890, "end_year": 890, "time_original": "890年十二月己丑条后", "dynasty": "唐", "description": "孙儒命沈粲守苏州，另遣其将归传道守润州。", "phases": [], "location_name": "苏州、润州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c3e548b8-c476-597a-84c5-52a80e8ad123"}, {"title": "丁会葛从周渡河取黎阳临河", "start_year": 890, "end_year": 890, "time_original": "890年十二月辛丑", "dynasty": "唐", "description": "汴将丁会、葛从周进击魏军，渡河取得黎阳、临河。", "phases": [], "location_name": "黎阳、临河", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5c8092c9-01dc-5888-a0ef-abf231a24a80"}, {"title": "庞师古霍存下淇门卫县，朱全忠继进", "start_year": 890, "end_year": 890, "time_original": "890年十二月辛丑条", "dynasty": "唐", "description": "庞师古、霍存攻下淇门、卫县，朱全忠随后率大军推进。", "phases": [], "location_name": "淇门、卫县", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9c8a2fb8-5160-506c-bfd4-4ed561a12063"}, {"title": "上元置升州，张雄任刺史", "start_year": 890, "end_year": 890, "time_original": "890年；原文是岁", "dynasty": "唐", "description": "朝廷在上元县置升州，以张雄为刺史。", "phases": [], "location_name": "上元县、升州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9863df9e-b5c0-5bff-acef-4a80e4923d13"}]'::jsonb)
