SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "王建急攻邛州，毛湘粮尽而救兵不到，向任可知表示不忍负田令孜、吏民无罪，愿其持己首归王建，随后沐浴待死。", "citation": "卷258·大顺元年（890）·zztj-v258-y0890-p037·原文件第68行", "note": "原文：邛州刺史毛湘，本田令孜亲吏，王建攻之急，食尽，救兵不至。壬戌，湘谓都知兵马使任可知曰：“吾不忍负田军容，吏民何罪！尔可持吾头归王建。”乃沐浴以俟刃。可知斩湘及二子降于建，士民皆泣。甲戌，建持永平旌节入邛州，以节度判官张琳知留后。缮完城隍，抚安夷獠，经营蜀、雅。冬，十月，癸未朔，建引兵还成都，蜀州将李行周逐徐公鉥，举城降建。；核对说明：田令孜本段为原亲吏关系及言语对象，不写其在城中；请求与临死准备分清，不补动机为现代判断。", "status": "draft", "id": "a4ab86c4-ffc1-55ff-8519-17a607b1f4b0", "subject_id": "58b06203-d8c1-588c-ad00-63263ac082c5", "source_id": "bd4c6687-4b2a-5664-a07b-3f5f5d44f014"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "890年闰月壬戌", "citation": "卷258·大顺元年（890）·zztj-v258-y0890-p037·原文件第68行", "note": "原文：邛州刺史毛湘，本田令孜亲吏，王建攻之急，食尽，救兵不至。壬戌，湘谓都知兵马使任可知曰：“吾不忍负田军容，吏民何罪！尔可持吾头归王建。”乃沐浴以俟刃。可知斩湘及二子降于建，士民皆泣。甲戌，建持永平旌节入邛州，以节度判官张琳知留后。缮完城隍，抚安夷獠，经营蜀、雅。冬，十月，癸未朔，建引兵还成都，蜀州将李行周逐徐公鉥，举城降建。；核对说明：田令孜本段为原亲吏关系及言语对象，不写其在城中；请求与临死准备分清，不补动机为现代判断。", "status": "draft", "id": "e7e9cb84-ce1b-5462-991c-4b01c654daad", "subject_id": "58b06203-d8c1-588c-ad00-63263ac082c5", "source_id": "bd4c6687-4b2a-5664-a07b-3f5f5d44f014"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记王建：攻城者。", "citation": "卷258·大顺元年（890）·zztj-v258-y0890-p037·原文件第68行", "note": "原文：邛州刺史毛湘，本田令孜亲吏，王建攻之急，食尽，救兵不至。壬戌，湘谓都知兵马使任可知曰：“吾不忍负田军容，吏民何罪！尔可持吾头归王建。”乃沐浴以俟刃。可知斩湘及二子降于建，士民皆泣。甲戌，建持永平旌节入邛州，以节度判官张琳知留后。缮完城隍，抚安夷獠，经营蜀、雅。冬，十月，癸未朔，建引兵还成都，蜀州将李行周逐徐公鉥，举城降建。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "4f257e27-9542-50f1-87c1-deb2603a3b19", "subject_id": "b02193d6-1c17-5154-bb7c-3295ed8dbbec", "source_id": "bd4c6687-4b2a-5664-a07b-3f5f5d44f014"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "王建：攻城者。", "citation": "卷258·大顺元年（890）·zztj-v258-y0890-p037·原文件第68行", "note": "原文：邛州刺史毛湘，本田令孜亲吏，王建攻之急，食尽，救兵不至。壬戌，湘谓都知兵马使任可知